contrato-calculadora.ejemplo-formula:
{
  "codigo": "CALC-NEFRO-002",
  "nombre": "CKD-EPI 2021 (sin raza)",
  "tipo": "formula",
  "cat": "Nefrología",
  "ver": 1,
  "hr": false,
  "paises": { "SV": true, "GT": true, "HN": true },
  "paginas": "*",
  "sub": "Tasa de filtración glomerular estimada",
  "ref": "Inker LA et al. NEJM 2021;385:1737",
  "def": {
    "inputs": [
      { "id": "crea", "label": "Creatinina", "u": "mg/dL", "min": 0.2, "max": 20, "val": 1 },
      { "id": "edad", "label": "Edad", "u": "años", "min": 18, "max": 110, "val": 60 },
      { "id": "sexo", "type": "select", "label": "Sexo",
        "opts": [
          { "v": "Masculino", "factor": 1,     "k": 0.9, "a": -0.302 },
          { "v": "Femenino",  "factor": 1.012, "k": 0.7, "a": -0.241 }
        ], "sel": 0 }
    ],
    "expr": "142 * min(crea/sexo_k,1)^sexo_a * max(crea/sexo_k,1)^-1.200 * 0.9938^edad * sexo_factor",
    "out": { "label": "TFGe", "u": "mL/min/1.73m²", "dec": 0 },
    "interp": [
      { "max": 14, "n": "critico", "t": "G5 — falla renal" },
      { "max": 29, "n": "critico", "t": "G4 — descenso grave" },
      { "max": 59, "n": "alerta",  "t": "G3 — descenso moderado" },
      { "n": "normal", "t": "G1–G2 — normal a leve" }
    ]
  }
}

contrato-calculadora.ejemplo-score:
{
  "codigo": "CALC-NEUM-008",
  "nombre": "SMART-COP",
  "tipo": "score",
  "cat": "Neumología",
  "ver": 1,
  "hr": false,
  "paises": { "SV": true, "GT": true, "HN": true },
  "paginas": ["evolucion","indicaciones","monitoreo"],
  "sub": "Necesidad de soporte vital en NAC",
  "ref": "Charles et al. 2008",
  "def": {
    "items": [
      { "id": "pas", "label": "PAS < 90 mmHg", "p": 2 },
      { "id": "ph",  "label": "pH < 7.35",     "p": 2 }
    ],
    "out": { "label": "SMART-COP", "u": "puntos", "dec": 0 },
    "interp": [
      { "max": 2, "n": "normal",  "t": "0–2: riesgo bajo" },
      { "n": "critico", "t": ">2: considerar UCI" }
    ]
  }
}

catalogo-pantallas.regla-resolucion:
// paginas: "*" (o indefinido) = visible en todas; arreglo = pantallas específicas; [] = ninguna
function pantallaVisible(calc, pantallaId) {
  const scope = calc.paginas === undefined ? "*" : calc.paginas;
  return scope === "*" || (Array.isArray(scope) && scope.includes(pantallaId));
}

motor-evaluacion.ejemplo-ternario:
// WFNS (HSA): grado calculado desde GCS y déficit focal
"expr": "gcs == 15 ? 1 : (gcs >= 13 ? (foc_g > 0 ? 3 : 2) : (gcs >= 7 ? 4 : 5))"
// CAM-ICU (delirium): F1 y F2 y (F3 o F4)
"expr": "(a_g and b_g and (c_g or d_g)) ? 1 : 0"
